INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180032,'36058','Mámoa do Rei','misterio','misterio_osm','O conxunto megalítico do Chan de Castiñeiras ou conxunto megalítico de Chan de Castiñeiras é un dos campos de mámoas máis importantes de Galiza. Atópase nas inmediacións do Parque de Cotorredondo e da Lagoa de Castiñeiras, entre os concellos de Vilaboa e Marín, na provincia de Pontevedra.',42.35832,-8.6726469,'https://gl.wikipedia.org/wiki/Chan_de_Castiñeiras');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180033,'36058','Mámoa de Castiñeiras','misterio','misterio_osm','A mámoa do Rei ou Chan de Castiñeiras 1 é un túmulo megalítico de aproximadamente 26 metros de diámetro e 2 metros de altura situado no concello de Vilaboa, a carón da lagoa de Castiñeiras. Está catalogado coma Ben de Interese Cultural.',42.3596013,-8.6724026,'https://gl.wikipedia.org/wiki/Mámoa_do_Rei_(Vilaboa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180034,'15073','Menhir de Olveira','misterio','misterio_osm','Menhir prehistórico en Ribeira (A Coruña), uno de los enclaves megalíticos rodeados de historia y leyenda.',42.5903156,-9.0341715);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180035,'15073','Dolmen de Axeitos','misterio','misterio_osm','O dolmen de Axeitos é un dos monumentos funerarios megalíticos de Galicia máis coñecidos. Sitúase na parroquia de San Martiño de Oleiros, no concello de Ribeira.',42.6000685,-9.0167702,'https://gl.wikipedia.org/wiki/Dolmen_de_Axeitos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180036,'36032','Lapa de Gargantáns','misterio','misterio_osm','A Lapa de Gargantáns é un menhir datado no neolítico, situada na parroquia de Gargantáns, no concello de Moraña (Pontevedra).',42.5697675,-8.5831481,'https://gl.wikipedia.org/wiki/Lapa_de_Gargantáns');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180037,'15034','Casota de Freáns','misterio','misterio_osm','A Casota de Freáns, tamén coñecida como Casota dos Mouros ou Casota de Berdoias é un dolmen situado na parroquia de Berdoias, concello de Vimianzo, de particulares características dentro do megalitismo galego. Estímase que foi construído entre o 2500 e o 2000 a.C. É de propiedade pública e está declarada como Ben…',43.0478542,-9.0863608,'https://gl.wikipedia.org/wiki/Casota_de_Freáns');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180038,'15092','Arca de Ogas','misterio','misterio_osm','Dolmen prehistórico en Vimianzo (A Coruña), uno de los enclaves megalíticos rodeados de historia y leyenda.',43.080516,-9.053413);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180039,'15092','A Mina de Recesindes','misterio','misterio_osm','A mina de Recesindes é parte dunha necrópole máis ampla: un campo de mámoas que se estende entre as parroquias de Carantoña e a de Calo, no concello de Vimianzo e ao sur da Pena Forcada. Forma parte do futuro Parque Arqueolóxico do Megalitismo da Costa da Morte.',43.1476929,-9.0734196,'https://gl.wikipedia.org/wiki/Mina_de_Recesindes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180040,'15093','Dolmen da Pedra da Lebre','misterio','misterio_osm','O dolmen de Pedra da Lebre, tamén coñecido como anta de Serramo, atópase na parroquia de Serramo, no concello de Vimianzo.',43.0699439,-8.9840068,'https://gl.wikipedia.org/wiki/Dolmen_de_Pedra_da_Lebre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180041,'15093','Dolmen de Pedra Moura de Monte Carnio','misterio','misterio_osm','O dolmen de Pedra Moura de Monte Carneo atópase entre as aldeas do Arxomil e Carnio, na parroquia de Treos, concello de Vimianzo.',43.0813446,-8.9778176,'https://gl.wikipedia.org/wiki/Dolmen_de_Pedra_Moura_de_Monte_Carneo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180042,'15092','Pedra Cuberta','misterio','misterio_osm','O dolmen de Pedra Cuberta atópase na parroquia de Treos, no concello de Vimianzo, preto da aldea do Arxomil.',43.0896793,-8.9843669,'https://gl.wikipedia.org/wiki/Dolmen_de_Pedra_Cuberta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180043,'15093','Dolmen de Pedra Vixía','misterio','misterio_osm','A Pedra Vixía é un monumento megalítico situado na parroquia de Lamas, no concello de Zas. Forma parte do Parque Arqueolóxico do Megalitismo da Costa da Morte.',43.1445452,-8.94424,'https://gl.wikipedia.org/wiki/Pedra_Vixía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180044,'90006','Fornela dos Mouros','misterio','misterio_osm','A Fornela dos Mouros ou dolmen do Aprazaduiro é un monumento megalítico situado na parroquia de Nande, no concello de Laxe. Forma parte do futuro Parque Arqueolóxico do Megalitismo da Costa da Morte.',43.167669,-9.0072559,'https://gl.wikipedia.org/wiki/Fornela_dos_Mouros');
