INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180196,'09216','Dolmen de Busnela','misterio','misterio_osm','El dolmen de Busnela es una formación pétrea situada al sur de la localidad burgalesa de Busnela, en un alto en la margen izquierda del río Nela (Castilla y León, España). Su estructura recuerda a la de un dolmen, aunque no hay evidencia que pruebe que sea tal.',43.0227417,-3.7804773,'https://es.wikipedia.org/wiki/Dolmen_de_Busnela');
