INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180201,'42151','Dolmen de San Gregorio','misterio','misterio_osm','El dolmen de San Gregorio, situado en la confluencia de los ríos Zarranzano y de los Royos, en Almarza, constituye un interesante ejemplo del fenómeno dolménico en la provincia de Soria (España), tanto por sus características constructivas como por constituir la constatación del fenómeno megalítico en esa…',41.9053828,-2.4559271,'https://es.wikipedia.org/wiki/Dolmen_de_San_Gregorio');
