INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180847,'07031','Talaiot de Capocorb d''en Jaquetó','misterio','misterio_osm','El talaiot de Capocorb d''en Jaquetó és un talaiot que ha quedat aïllat del conjunt del qual formava part, el poblat talaiòtic de Capocorb Vell, al municipi de Llucmajor, Mallorca. Les seves característiques són semblants a la dels tres talaiots circulars del poblat.',39.4,2.8275,'https://ca.wikipedia.org/wiki/Talaiot_de_Capocorb_d''en_Jaquetó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180848,'07031','Talaiot de Can Mòger','misterio','misterio_osm','El talaiot de can Mòger és un jaciment arqueològic prehistòric de la cultura talaiòtica, corresponent a un poblat, situat al lloc anomenat es Campot, a la possessió de can Mòger, al municipi de Llucmajor, Mallorca. Pren el nom d''un talaiot de planta rectangular ben visible que es conserva en bon estat al qual se li…',39.4240532,2.8499707,'https://ca.wikipedia.org/wiki/Talaiot_de_Can_Mòger');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180849,'90018','Son Boronat (yacimiento)','misterio','misterio_osm','Son Boronat es un yacimiento arqueológico que se encuentra en la isla de Mallorca, en el término municipal de Calviá, en la montaña “es Penyal des Migdia”, perteneciente a la sierra de Na Burguesa, a 360 metros de altitud sobre el nivel del mar. El yacimiento no es más que una cueva excavada en la pared de la…',39.56126,2.54225,'https://es.wikipedia.org/wiki/Son_Boronat_(yacimiento)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180850,'07031','Talaiot de Son Taixaquet des Llobets','misterio','misterio_osm','El talaiot de Son Taixaquet des Llobets és un talaiot situat just devora les cases de la possessió de Son Taixaquet, al municipi de Llucmajor, Mallorca. Pertany al període de la cultura talaiòtica, el seu portal està orientat al sud-est i té planta rectangular, amb 10,7 m de diàmetre màxim per 2,6 m d''alçària.',39.454111,2.85363,'https://ca.wikipedia.org/wiki/Talaiot_de_Son_Taixaquet_des_Llobets');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180851,'07031','Talaiot de Son Taixaquet d''en Ramonell','misterio','misterio_osm','El talaiot de Son Taixaquet d''en Ramonell o talaiot d''en Ramonell és un talaiot de planta quadrada, construït el període de la cultura talaiòtica, aïllat, situat just a una parcel·lació de la possessió de Son Taixaquet, anomenada can Ramonell, al municipi de Llucmajor, Mallorca. És un talaiot aïllat però que…',39.4598095,2.854047,'https://ca.wikipedia.org/wiki/Talaiot_de_Son_Taixaquet_d''en_Ramonell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180852,'07031','Talaiot de Son Noguera','misterio','misterio_osm','El Talaiot de Son Noguera és un talaiot circular de gran bellesa situat just al costat de les cases de la possessió de Son Noguera, al municipi de Llucmajor, Mallorca. És obra de la cultura talaiòtica i es troba actualment aïllat.',39.4825888,2.8589969,'https://ca.wikipedia.org/wiki/Talaiot_de_Son_Noguera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180853,'07031','Habitacions de Son Noguera - Pleta des Forn de Calç','misterio','misterio_osm','Les habitacions de Son Noguera - Es Forn de Calç és un jaciment arqueològic prehistòric situat a la possessió de Son Noguera, a la pleta anomenada des Forn de Calç, al municipi de Llucmajor, Mallorca. En aquest jaciment hi destaca una habitació prehistòrica de planta rectangular, les quals dimensions són 6,4 m de…',39.4843673,2.8601535,'https://ca.wikipedia.org/wiki/Habitacions_de_Son_Noguera_-_Pleta_des_Forn_de_Calç');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180854,'07047','Ses Talaies de Can Xim','misterio','misterio_osm','Ses Talaies de Ca''n Xim o Talaiots de Cascanar són un conjunt prehistòric integrat per dos talaiots de planta quadrada i dos recintes adossats a un d''aquests. La unitat està situada a poca distància del poblat prehistòric de Cascanar, en el municipi de Sencelles a l''illa de Mallorca.',39.6364478,2.9176484,'https://ca.wikipedia.org/wiki/Ses_Talaies_de_Can_Xim');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180855,'07025','Talaiot de Coma-sema','misterio','misterio_osm','El talaiot de Coma Sema o talaiot des Pins de sa Bassa és un talaiot circular enrevoltat de les restes annexes d''una altra edificació i un mur, situat a la possessió de Coma-sema (Bunyola).',39.7588487,2.7805395,'https://ca.wikipedia.org/wiki/Talaiot_de_Coma-sema');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180856,'07055','Sepulcre megalític de Son Bauló de Dalt','misterio','misterio_osm','El dolmen de Son Bauló de Dalt és un jaciment dolmènic situat al polígon industrial de Son Bauló, vora can Picafort. Fou descobert per un aficionat, el qual va publicar una primera referència al Bulletin de la Société Préhistorique Française a mitjan segle xx, però no fou fins als anys seixanta que un equip…',39.7538775,3.158649,'https://ca.wikipedia.org/wiki/Dolmen_de_Son_Bauló_de_Dalt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180857,'08003','Dolmen de la Vinya Monera','misterio','misterio_osm','Menhir prehistórico en Barcelona (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.370055,2.15792);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180858,'08124','Menhir de Mollet','misterio','misterio_osm','El menhir de Mollet és un megàlit del Neolític de 4,90 m de llargada, 68 cm d''amplada i 110 cm de fondària, amb un pes de 6 tones, trobat en el jaciment pla de les Pruneres, dins del nucli urbà de Mollet del Vallès (Vallès Oriental), declarat Bé cultural d''interès nacional en la categoria de Monument històric. Té…',41.5375,2.20972,'https://ca.wikipedia.org/wiki/Menhir_de_Mollet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180859,'08256','Menhir de Castellruf','misterio','misterio_osm','El Menhir de Castellruf es troba a Santa Maria de Martorelles (el Vallès Oriental), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya.',41.519897,2.2535507,'https://ca.wikipedia.org/wiki/Menhir_de_Castellruf');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180860,'08256','Dolmen de Castellruf','misterio','misterio_osm','El Dolmen de Castellruf es troba al Parc de la Serralada Litoral, concretament al municipi de Santa Maria de Martorelles (Vallès Oriental).',41.5131305,2.2669575,'https://ca.wikipedia.org/wiki/Dolmen_de_Castellruf');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180861,'08256','Dolmen de Can Gurri','misterio','misterio_osm','El Dolmen de Can Gurri, també conegut com a Dolmen del Collet de Can Gurri, UTM: 31 N - 439983 - 4596351. Dolmen de la Font d''en Gurri o Roca d''en Mayal, és un dolmen ubicat al Parc de la Serralada Litoral, dins el terme municipal de Martorelles (Vallès Oriental), inclòs a l''Inventari del Patrimoni Arqueològic i…',41.5165776,2.2806507,'https://ca.wikipedia.org/wiki/Dolmen_de_Can_Gurri');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180862,'08230','Menhir de la Pedra del Diable','misterio','misterio_osm','El Menhir de la Pedra del Diable es troba al Parc de la Serralada Litoral, concretament a Vilassar de Dalt (Maresme), declarat bé cultural d''interès local.',41.5250314,2.3297511,'https://ca.wikipedia.org/wiki/Menhir_de_la_Pedra_del_Diable');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180863,'08296','Roca Foradada de Vallromanes','misterio','misterio_osm','La Roca Foradada de Vallromanes o la Roca del Turó de Cal Tàvec es troba al Parc de la Serralada Litoral i és la resta arqueològica més antiga de Vallromanes (Vallès Oriental), declarada Bé cultural d''interès local.',41.5335669,2.3111597,'https://ca.wikipedia.org/wiki/Roca_Foradada_de_Vallromanes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180864,'08296','Dolmen Fals de Can Maimó','misterio','misterio_osm','El Dolmen Fals de Can Maimó es troba al Parc de la Serralada Litoral, concretament a Vilanova del Vallès (el Vallès Oriental).',41.5359511,2.3133105,'https://ca.wikipedia.org/wiki/Dolmen_Fals_de_Can_Maimó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180865,'08214','Roca d''en Toni','misterio','misterio_osm','El Dolmen de Can Boquet o Roca d''en Toni que es troba al Parc de la Serralada Litoral, concretament a Vilassar de Dalt (el Maresme), va ser declarat bé cultural d''interès nacional en la categoria de Zona arqueològica.',41.5321619,2.341995,'https://ca.wikipedia.org/wiki/Dolmen_de_Can_Boquet');
