INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180868,'25150','Jaciment arqueològic de Reguers de Seró','misterio','misterio_osm','El Túmul dels Reguers de Seró és una estructura megalítica situada al municipi d''Artesa de Segre, (La Noguera), declarat Bé cultural d''interès nacional. Va ser descobert l''any 2007 durant la construcció de la xarxa de reg Segarra-Garrigues a uns 7 kilòmetres d''Artesa de Segre municipi de la comarca de la Noguera.',41.8848965,1.1196564,'https://ca.wikipedia.org/wiki/Jaciment_arqueològic_de_Reguers_de_Seró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180869,'08185','Sepulcre Megalític de les Maioles','misterio','misterio_osm','El Sepulcre Megalític de les Maioles és un dolmen de Rubió (Anoia), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a l''inici de la serralada de Rubió, al costat d''una via de comunicació d''origen molt antic i que ha estat utilitzada al llarg del temps com a pas de ramats de les…',41.66667,1.59444,'https://ca.wikipedia.org/wiki/Sepulcre_Megalític_de_les_Maioles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180870,'08170','Dolmen dels Tres Reis','misterio','misterio_osm','El dolmen dels Tres Reis és un sepulcre megalític al límit de Rubió i Prats de Rei (Anoia), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Està situat a la Serra de Rubió, en el punt més alt de la carena.',41.6847361,1.5798472,'https://ca.wikipedia.org/wiki/Dolmen_dels_Tres_Reis');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180871,'08189','Dolmen de Serragallarda','misterio','misterio_osm','Dolmen prehistórico en Salavinera (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.744508,1.5939038);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180872,'25129','Dolmen de Llanera','misterio','misterio_osm','El dolmen de Llanera, també anomenat Torre dels Moros, o Dolmen de la Vila de la Gola dels Bous és un monument megalític de Llanera (Solsonès), declarat Bé cultural d''interès local. És probablement el més gran i també el més ben conservat de Catalunya.',41.8986784,1.4757973,'https://ca.wikipedia.org/wiki/Dolmen_de_Llanera');
