INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180881,'25202','Dolmen de Sant Roc','misterio','misterio_osm','El Dolmen de Sant Roc, o Cabaneta del Moro, és un dolmen del terme municipal de Senterada, del Pallars Jussà, prop del poble de Cérvoles. Està situat a 1.228 msnm en el sector sud del terme, en el Bosc de Cérvoles, a llevant de Colliberri, al sud de Cadolla i al sud-oest de Naens.',42.3015507,0.9062641,'https://ca.wikipedia.org/wiki/Dolmen_de_Sant_Roc');
