INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180884,'25201','Dolmen de la Casa Encantada','misterio','misterio_osm','La Casa Encantada és un dolmen del terme de Senterada, (Pallars Jussà), declarat Bé cultural d''interès local. Sovint és associat al poble de Pinyana, que pertany al terme municipal del Pont de Suert, a causa de la seva proximitat.',42.3433553,0.8906439,'https://ca.wikipedia.org/wiki/La_Casa_Encantada_(Senterada)');
