INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180887,'25565','Sepulcre megalític de la Cabana de Perauba','misterio','misterio_osm','El sepulcre megalític de la Cabana de Perauba o de Peralba és un dolmen situat al terme municipal de Baix Pallars (Pallars Sobirà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a 1306 msnm, al vessant nord de la Serra de Peracalç (1478 m), al final del contrafort muntanyós…',42.3154324,0.9849122,'https://ca.wikipedia.org/wiki/Sepulcre_megalític_de_la_Cabana_de_Perauba');
