INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180890,'25565','la Cabaneta','misterio','misterio_osm','El Dolmen de la Cabaneta és un monument megalític de l''edat del bronze (fa 4000-4500 anys) de la Torre de Cabdella (Pallars Jussà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Aquest dolmen és l''únic del municipi de la Torre de Capdella, i destaca pel seu bon estat de conservació.',42.3537434,0.995143,'https://ca.wikipedia.org/wiki/Dolmen_de_la_Cabaneta');
