INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180893,'25064','Dolmen de Ceuró 1','misterio','misterio_osm','La necròpolis de Ceuró és un conjunt de tres cistes pertanyent al Neolític mitjà entre el 3.500 i el 2500 aC. que està ubicada a la riba dreta de la rasa de les Grioles, a 1 km al SE del poblet de Ceuró (Castellar de la Ribera, Solsonès, declarades Espai de Protecció Arqueològica.',42.0154057,1.3825051,'https://ca.wikipedia.org/wiki/Necròpolis_de_Ceuró');
