INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180913,'08064','Dolmen del Criac','misterio','misterio_osm','Dolmen prehistórico en Castelltersol (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.747162,2.0936478);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180914,'08229','Dolmen de Betlem','misterio','misterio_osm','El Dolmen de Betlem o hemidolmen de Sant Andreu es troba a Fonollosa (Bages), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Així s''anomenava a les pedres que es podien veure d''una torre de contrapès de premsa de vi medieval descoberta l''any 2019, en el jaciment arqueològic del Pla de…',41.7797981,1.7126588,'https://ca.wikipedia.org/wiki/Dolmen_de_Betlem');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180915,'08229','Dolmen de Castelltallat','misterio','misterio_osm','Dolmen prehistórico en San Mateo de Bages (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.8121429,1.6785656);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180916,'08128','Dolmen del Trompo','misterio','misterio_osm','El Dolmen del Trompo és una construcció feta amb grans pedres a l''època neolítica, de Castellcir, (Moianès), descrit a la bibliografia i declarat Bé cultural d''interès local. És un megàlit del tipus de cambra simple, de mida força gran.',41.767249,2.045431,'https://ca.wikipedia.org/wiki/Dolmen_del_Trompo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180917,'08128','Dolmen de la Clusella','misterio','misterio_osm','El dolmen de la Clusella o Crusella és un megàlit del Eneolític del terme municipal de Castellcir, (Moianès), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a uns 500 metres al nord-oest de la masia de la Clusella, a la Vall de Marfà.',41.77056,2.05944,'https://ca.wikipedia.org/wiki/Dolmen_de_la_Clusella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180918,'08064','Dolmen del Mas Clamí','misterio','misterio_osm','Dolmen prehistórico en Castelltersol (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.7624525,2.0949912);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180919,'08138','Dolmen de Santa Magdalena','misterio','misterio_osm','El Dolmen de Santa Magdalena és un monument megalític del terme municipal de Moià, (Moianès), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a la zona central de la Serra de Santa Magdalena, dins el terme municipal de Moià, a l''extrem sud-oest d''aquest terme.',41.794368,2.060567,'https://ca.wikipedia.org/wiki/Dolmen_de_Santa_Magdalena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180920,'08156','Menhir de Pedra Llarga o de la Pedra del Diable','misterio','misterio_osm','Menhir prehistórico en Paláu Solitar y Plegamans (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.5805966,2.1799847);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180921,'90590','Dòlmen de Serra Cavallera','misterio','misterio_osm','Dolmen prehistórico en Sentmenat (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.6274357,2.1156119);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180922,'08064','Dolmen del Gavatx','misterio','misterio_osm','El dolmen del Gavatx és una estructura megalítica del municipi de Castellterçol, (Moianès), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a l''oest del nucli de Castellterçol.',41.7427215,2.1101068,'https://ca.wikipedia.org/wiki/Dolmen_del_Gavatx');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180923,'08296','Roca Foradada de Can Nadal/Cova d''en Nadal','misterio','misterio_osm','La Roca Foradada de Can Nadal o la Cova de l''Ermità es troba al Parc de la Serralada Litoral, concretament a Vilanova del Vallès (el Vallès Oriental), al cim del Turó de Can Nadal, amb la Cambra Megalítica de Can Nadal, està inclosa a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. És la més…',41.547291,2.32132,'https://ca.wikipedia.org/wiki/Roca_Foradada_de_Can_Nadal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180924,'08181','Dolmen de Can Gol II','misterio','misterio_osm','El Dolmen de Can Gol II és un monument megalític que es troba al Parc de la Serralada Litoral, a la Roca del Vallès (Vallès Oriental), declarat Bé cultural d''interès local. És el més petit de tot el susdit parc.',41.5650412,2.3181109,'https://ca.wikipedia.org/wiki/Dolmen_de_Can_Gol_II');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180925,'08181','Dolmen de Can Gol I','misterio','misterio_osm','El Dolmen de Can Gol I es troba al Parc de la Serralada Litoral, a la Roca del Vallès,(Vallès Oriental) i fou declarat Bé cultural d''interès local. Fou descobert l''any 1946 per Josep Estrada i l''Agrupació Excursionista de Granollers.',41.5635885,2.3139426,'https://ca.wikipedia.org/wiki/Dolmen_de_Can_Gol_I');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180926,'08181','Roca Foradada de Can Gol','misterio','misterio_osm','La Roca Foradada de Can Gol es troba al Parc de la Serralada Litoral, concretament a Vilanova del Vallès (el Vallès Oriental). És un gran bloc granític d''uns 40 metres cúbics (4,5 x 2,5 x 3,5 m) amb una entrada arran de terra, lleugerament ogival, de gairebé un metre de diàmetre.',41.5635701,2.3178879,'https://ca.wikipedia.org/wiki/Roca_Foradada_de_Can_Gol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180927,'08153','Menhir de Cal Camat','misterio','misterio_osm','Menhir prehistórico en Orrius (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.5421877,2.3468346);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180928,'08181','La Pedra de les Orenetes','misterio','misterio_osm','La Pedra de les Orenetes es troba al Parc de la Serralada Litoral, concretament al terme municipal de la Roca del Vallès al sector de Céllecs, (Vallès Oriental), declarat Patrimoni de la Humanitat.',41.5667224,2.3244351,'https://ca.wikipedia.org/wiki/Pedra_de_les_Orenetes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180929,'08181','Pedra de les Creus','misterio','misterio_osm','La Pedra de les Creus es troba al Parc de la Serralada Litoral, concretament a la Roca del Vallès (el Vallès Oriental), declarat Bé cultural d''interès local en la categoria de Zona arqueològica.',41.5677066,2.3233974,'https://ca.wikipedia.org/wiki/Pedra_de_les_Creus');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180930,'08181','Dolmen de Céllecs','misterio','misterio_osm','El Dolmen de Céllecs, dolmen de Séllecs, dolmen de la Cabana del Moro de Céllecs, dolmen de la Cabana del Moro, Cava del Moro o Cabana del Moro es un megàlit del Eneolític de La Roca del Vallès, (Vallès Oriental), declarat Bé cultural d''interès local. Es troba al Parc de la Serralada Litoral.',41.5666626,2.3317891,'https://ca.wikipedia.org/wiki/Dolmen_de_Céllecs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180931,'08075','Pedra Gravada del Turó dels Castellans','misterio','misterio_osm','La Pedra Gravada del Turó dels Castellans o Pedra Gravada de Parpers es troba al Parc de la Serralada Litoral, concretament a Argentona (el Maresme), declarat Bé cultural d''interès nacional en qualitat de Zona arqueològica. Fou descoberta l''agost del 1990 pels vigilants forestals Oriol Bassa i Felip Castells.',41.59361,2.3775,'https://ca.wikipedia.org/wiki/Pedra_Gravada_del_Turó_dels_Castellans');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180932,'08075','Cau de la Mostela II','misterio','misterio_osm','Monumento megalítico prehistórico en Dosrius (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.6103331,2.3873661);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180933,'08046','Cromlec de Pins Rosers','misterio','misterio_osm','El cromlec de Pins Rosers, també anomenat dolmen de Pins Rosers o, popularment, Pedres del Diable, és un petit conjunt megalític que es troba dins d''una depuradora d''aigües, al terme municipal de Llinars del Vallès, a prop dels de Cardedeu, La Roca del Vallès i Santa Agnès de Malanyanes (Vallès Oriental), declarat…',41.62087,2.3628,'https://ca.wikipedia.org/wiki/Cromlec_de_Pins_Rosers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180934,'08075','Menhir de la Costa de Can Martorell','misterio','misterio_osm','Dolmen prehistórico en Dosrius (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.5938916,2.4152329);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180935,'08306','Menhir de Ca l''Arenes II','misterio','misterio_osm','Menhir prehistórico en Villalba Saserra (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.6179308,2.4613868);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180936,'08306','Menhir de Ca l''Arenes III','misterio','misterio_osm','Dolmen prehistórico en Villalba Saserra (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.6235932,2.4638692);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180937,'08306','Dolmen de Ca l''Arenes','misterio','misterio_osm','El Dolmen de Ca l''Arenes és un dolmen situat al Parc Natural del Montnegre i el Corredor, dins el terme municipal de Dosrius (el Maresme), declarat Bé cultural d''interès local. Es troba a l''entorn megalític de la serra del Corredor, on també hi ha altres dòlmens com ara el de la Pedra Gentil, de Pedrarca, de les…',41.6267491,2.4611073,'https://ca.wikipedia.org/wiki/Dolmen_de_Ca_l''Arenes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180938,'08294','Pedra Llarga','misterio','misterio_osm','Dolmen prehistórico en Vallgorguina (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.6239822,2.4929121);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180939,'08294','Pedra del Coll del Pi d''en Buac','misterio','misterio_osm','Dolmen prehistórico en Vallgorguina (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.6241125,2.49853);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180940,'08306','Dolmen de Pedra Arca','misterio','misterio_osm','El Dolmen de Pedrarca, o Pedra Arca, és una construcció funerària que es troba al municipi de Vilalba Sasserra, (Vallès Oriental), declarat Bé cultural d''interès local. És de planta rectangular i amb una gran llosa de coberta del Neolític.',41.6516944,2.4351426,'https://ca.wikipedia.org/wiki/Dolmen_de_Pedrarca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180941,'08294','Dolmen de Pedra Gentil','misterio','misterio_osm','La Pedra Gentil és una estructura megalítica del municipi de Vallgorguina, (Vallès Oriental), declarat Bé cultural d''interès local. El dolmen, d''uns 4.000 anys, és un sepulcre dels anomenats de cambra simple.',41.6518454,2.4868748,'https://ca.wikipedia.org/wiki/Pedra_Gentil');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180942,'08055','Dolmen de les Umbertes','misterio','misterio_osm','El Dolmen de les Umbertes és un megàlit del neolític del terme municipal de Moià, (Moianès), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Està situat en el camp de vol de Les Umbertes, al vessant sud-est de la intersencció entre les dues pistes de vol.',41.7855485,2.1294157,'https://ca.wikipedia.org/wiki/Dolmen_de_les_Umbertes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180943,'08055','Dolmen de la Casa Nova','misterio','misterio_osm','El Dolmen de la Casa Nova o Verdeguer és un megàlit del neolític del terme municipal de Castellcir, (Moianès), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Està situat a migdia de la Casa Nova del Verdeguer, a llevant de la Casa del Guarda i al nord-est de la masia del Verdeguer.',41.78333,2.13333,'https://ca.wikipedia.org/wiki/Dolmen_de_la_Casa_Nova');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180944,'90578','Cista de Perers','misterio','misterio_osm','Cista megalítica prehistórico en Moià (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.8115335,2.140076);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180945,'08011','Dolmen de Puig Rodó','misterio','misterio_osm','El Dolmen de Puig Rodó és un megàlit d''inicis del mil·lenni III aC, en el Neolític mitjà, del terme municipal de Moià, (Moianès), declarat Bé cultural d''interès local. Està situat al GR-3, GR-177 (lat: 41.81276, lon:2.09701), on hi ha un dipòsit d''aigua per als bombers i al vessant sud-oriental del Puig Rodó que li…',41.8474225,2.1282511,'https://ca.wikipedia.org/wiki/Dolmen_de_Puig_Rodó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180946,'08070','Dolmen del Cuspinar','misterio','misterio_osm','Dolmen prehistórico en Collsuspina (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.81167,2.15028);
