INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180948,'90876','Dolmen Tomba de l''Ollic','misterio','misterio_osm','Dolmen prehistórico en Aiguafreda (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.7827771,2.2391669);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180949,'90876','Dolmen Cruïlles','misterio','misterio_osm','Els dòlmens de la Serra de l''Arca formen un grup de set sepulcres megalítics de la serra de l''Arca. Amb la paraula arca es designava en èpoques anteriors les construccions megalítiques.',41.7804875,2.2607741,'https://ca.wikipedia.org/wiki/Dolmen_de_Cruïlles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180950,'90876','Tomba de Casanova de Can Serra','misterio','misterio_osm','Dolmen prehistórico en Aiguafreda (Barcelona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.7778369,2.2671835);
