INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180954,'08137','Estela de la Calma','misterio','misterio_osm','L''Estela de la Calma o la Sitja del Llop és un megàlit del Montseny (Vallès Oriental), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es va trobar l''any 1976 al Pla de la Calma, al massís del Montseny, i actualment està exposat dins d''una urna de vidre al poble de Montseny.',41.76069,2.3372272,'https://ca.wikipedia.org/wiki/Estela_de_la_Calma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180955,'90591','Jaciment de la Pedra del Sacrifici','misterio','misterio_osm','La Pedra del Sacrifici és un jaciment prehistòric que es troba a Tavèrnoles (Osona), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a Savassona, en els primers contraforts eocènics que formen les Guilleries i a la riba dreta del riu Ter.',41.95889,2.34167,'https://ca.wikipedia.org/wiki/Jaciment_de_la_Pedra_del_Sacrifici');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180956,'08190','Dolmen de Molers','misterio','misterio_osm','El dolmen de Molers o dolmen de Cal Xisquet de Maçaners, situat dins el terme municipal de Saldes (Solsonés), declarat Bé cultural d''interès local. És un dels megàlits més importants dels trobats dins la comarca del Berguedà, a més de ser-ne el més septentrional.',42.2294427,1.7623425,'https://ca.wikipedia.org/wiki/Dolmen_de_Molers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180957,'08254','Dolmen de Puigsespedres','misterio','misterio_osm','El Dolmen de Puigsespedres és un sepulcre megalític situat a 765 m al costat del turó de Puigsespedres. És prop del Camí Ral de Vic a Olot, a un km damunt del poble de l''Esquirol (Osona), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya.',42.0332648,2.3791853,'https://ca.wikipedia.org/wiki/Dolmen_de_Puigsespedres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180958,'08294','Pedra de les Olles','misterio','misterio_osm','La Pedra de les Olles o Pedra del Pla dels Forcs és un agrupament d''uns grans pedres granítiques amb més de vint inscultures en cassoletes gravades per humans. Es troba a l''àmbit del Montnegre al terme municipal de Sant Iscle de Vallalta (El Maresme), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic…',41.6488955,2.5444369,'https://ca.wikipedia.org/wiki/Pedra_de_les_Olles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180959,'18017','Paradolmen de Ses Rates','misterio','misterio_osm','El paradolmen anomenat popularment Paradolmen de Ses Rates és un monument megalític del Massís de Cadiretes, al municipi de Tossa de Mar, (La Selva), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Disposa d''una doble cambra coberta per una gran llosa granítica.',41.7508,2.91983,'https://ca.wikipedia.org/wiki/Paradolmen_de_Ses_Rates');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180960,'18017','Paradolmen d''en Garcia','misterio','misterio_osm','El Paradolmen d''en Garcia és un paradolmen megalític del Massís de Cadiretes, al municipi de Tossa de Mar, (La Selva), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. La cambra sepulcral està formada per un bloc erràtic a ponent i amb la penya natural a llevant.',41.75194,2.92833,'https://ca.wikipedia.org/wiki/Paradolmen_d''en_Garcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180961,'18017','Menhir d''en Llac','misterio','misterio_osm','El menhir d''en Llach està situat a prop de Can Cabanyes al Puig de Cadiretes al terme municipal de Llagostera (Gironès), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. És de granit rosat-negrós i de tipus fal·liforme, i mesura 74 cm d''ample per 76 de gruix, amb una alçada de 265 cm.',41.7593198,2.9350783,'https://ca.wikipedia.org/wiki/Menhir_d''en_Llach');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180962,'18017','Pedra Sobre Altra (paradolmen)','misterio','misterio_osm','La Pedra Sobre Altra és un monument megalític del Massís de Cadiretes, al municipi de Tossa de Mar, (La Selva), declarat Bé cultural d''interès local. Està catalogat com a paradolmen.',41.760604,2.9404678,'https://ca.wikipedia.org/wiki/Pedra_Sobre_Altra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180963,'18017','Pedra dels Sacrificis de Can Cabanyes','misterio','misterio_osm','La Pedra dels Sacrificis de Can Cabanyes de Llagostera és una pedra amb gravats de cronologia indeterminada de Llagostera (Gironès), inclosa a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. És un bloc erràtic de granit que amida 1,20 x 1,15 x 0,70 i es troba en una zona de bosc molt dens…',41.7701662,2.9431491,'https://ca.wikipedia.org/wiki/Pedra_dels_Sacrificis_de_Can_Cabanyes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180964,'17181','Menhir de Can Llaurador','misterio','misterio_osm','Menhir prehistórico en Santa Cristina de Aro (Girona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.8040294,2.9698291);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180965,'17181','"Dolmen del Mas Bou-serenys"','misterio','misterio_osm','El dolmen del Mas Bou-serenys (2.700-2.500 aC) és un sepulcre de corredor recent, situat a la urbanització de la Roca de Malvet, al municipi de Santa Cristina d''Aro (Baix Empordà), declarat Bé cultural d''interès local. Fa uns 6 m.',41.8330779,2.9971695,'https://ca.wikipedia.org/wiki/Dolmen_del_Mas_Bou-serenys');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(180966,'17160','Menhir de Cala Pedrosa','misterio','misterio_osm','Menhir prehistórico en San Feliu de Guíxols (Girona), uno de los enclaves megalíticos rodeados de historia y leyenda.',41.791282,3.0574188);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180967,'17181','Dolmen de la Cova d''en Daina','misterio','misterio_osm','La cova d''en Daina és un dolmen de granit de grans dimensions construït entre el 2700 aC i el 2200 aC al raval del poble de Romanyà de la Selva (Baix Empordà), declarat Bé cultural d''interès local en la categoria de Zona arqueològica.',41.8571228,2.9927,'https://ca.wikipedia.org/wiki/Cova_d''en_Daina');
