INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180969,'17901','Menhir de Sant Sadurní','misterio','misterio_osm','El menhir de Sant Sadurní o Pedra dreta de Sant Sadurní és un menhir situat al terme de Sant Sadurní de l''Heura al paratge de Can Mateu de la Creu (Baix Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Va ser identificat per Josep Pella i Forgas el 1877.',41.951883,2.981214,'https://ca.wikipedia.org/wiki/Menhir_de_Sant_Sadurní');
