INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180988,'17137','Dolmen de les Closes','misterio','misterio_osm','El dolmen de les Closes o de Pujarnol és l''únic dolmen conegut actualment al terme municipal de Porqueres (Pla de l''Estany), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Està situat en un replà al vessant oriental del Puig Surís a uns 260 metres sobre el nivell del mar.',42.0985885,2.732311,'https://ca.wikipedia.org/wiki/Dolmen_de_les_Closes_(Porqueres)');
