INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(180997,'17128','Dolmen de la Vinya del Rei','misterio','misterio_osm','El Dolmen de la Vinya del Rei és un sepulcre del tipus corredor del IV-II Mil·lenni aC. Aquest megàlit és el més gran del terme de Vilajuïga (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. El seu emplaçament en un lloc gens dominant és excepcional.',42.3296166,3.1238055,'https://ca.wikipedia.org/wiki/Dolmen_de_la_Vinya_del_Rei');
