INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181038,'90896','Menhir de Vilartolí','misterio','misterio_osm','El Menhir de Vilartolí o Menhir de Santa Fé és un jaciment neolític que es troba a Sant Climent Sescebes (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a 0,5 km al nord del veïnat de Vilartolí, al peu de la pista que comunica Vilartolí amb Requesens i és molt…',42.39167,2.96806,'https://ca.wikipedia.org/wiki/Menhir_de_Vilartolí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181039,'17064','Dolmen de la Cabana Arqueta','misterio','misterio_osm','El dolmen de la cabana Arqueta o Cova dels Alarbs és un dolmen situat al terme municipal d''Espolla(Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. És un dels dòlmens d''Espolla, no gaire lluny de la línia divisòria amb el terme de Sant Climent Sescebes i molt proper a la…',42.3846597,2.988153,'https://ca.wikipedia.org/wiki/Dolmen_de_la_Cabana_Arqueta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181040,'90896','Dolmen del Prat Tancat','misterio','misterio_osm','El Dolmen del Prat Tancat és un dolmen a dos quilòmetres a l''est del nucli urbà al terme municipal de Sant Climent Sescebes, (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a prop del Dolmen de la Cabana Arqueta i del Dolmen de Tires Llargues.',42.3894707,2.9791423,'https://ca.wikipedia.org/wiki/Dolmen_del_Prat_Tancat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181041,'90896','Dolmen de la Gutina','misterio','misterio_osm','Plantilla:Confusisió El dolmen de la Gutina és un dolmen situat al terme municipal de Sant Climent Sescebes, (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Es troba a l''antic camí que comunicava Espolla amb Vilartolí, en el paratge anomenat la Gutina.',42.3964092,2.9804157,'https://ca.wikipedia.org/wiki/Dolmen_de_la_Gutina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181042,'90896','Dolmen de Tires Llargues','misterio','misterio_osm','El Dolmen de Tires Llargues és un jaciment arqueològic megalític que es troba a Sant Climent Sescebes, (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya.',42.3947725,2.9786374,'https://ca.wikipedia.org/wiki/Dolmen_de_Tires_Llargues');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181043,'17064','Dolmen del Puig de Pal','misterio','misterio_osm','El Dolmen de la Gutina/Puig del Pal és un dolmen situat al terme municipal d''Espolla, (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Forma part d''un dels Dòlmens d''Espolla.',42.395316,2.985515,'https://ca.wikipedia.org/wiki/Dolmen_de_la_Gutina/Puig_del_Pal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181044,'90896','Menhir de la Murtra','misterio','misterio_osm','El menhir de la Murtra o Pedra Gentil és un menhir situat al terme municipal de Sant Climent Sescebes, (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. És molt proper al menhir del Castellà i al menhir de Vilartolí.',42.4025456,2.9777796,'https://ca.wikipedia.org/wiki/Menhir_de_la_Murtra_(Sant_Climent_Sescebes)');
