INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181047,'17064','Menhir del Castellà','misterio','misterio_osm','El Menhir del Castellà o de Roques Blanques és un menhir situat al terme municipal d''Espolla, (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Situat vers el nord-oest del centre urbà, a uns 2 km, però actualment la pista d''accés ha quedat molt malmesa.',42.41472,2.98083,'https://ca.wikipedia.org/wiki/Menhir_del_Castellà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181048,'17064','Dolmen de les Morelles','misterio','misterio_osm','El Dolmen de les Morelles és un dolmen situat al terme municipal d''Espolla, (Alt Empordà), inclòs a l''Inventari del Patrimoni Arqueològic i Paleontològic de Catalunya. Forma part dels Dòlmens d''Espolla, situat en el paratge de les Morelles o de la Mina, a uns 3 km del centre urbà en direcció nord.',42.42667,2.99083,'https://ca.wikipedia.org/wiki/Dolmen_de_les_Morelles');
