INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181086,'49092','Dólmen de San Adrián','misterio','misterio_osm','El dolmen de San Adrián es un megalito prehistórico situado al norte de la localidad zamorana de Granucillo (Castilla y León, España) y fechado entre hace 3500 y 3000 años. Se encuentra en el pago de La Horca, en la vega del arroyo Almucera, sobre un pequeño alto, muy cerca de la ermita homónima, bien señalizado y…',42.054076,-5.9196528,'https://es.wikipedia.org/wiki/Dolmen_de_San_Adrián');
