INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181091,'90040','Círculo Lítico da Roda','misterio','misterio_osm','O henge de Roda, coñecido como A roda de Barreiros, é unha estrutura megalítica situada na aldea de Roda (San Pedro de Benquerencia, Barreiros). Foi a primeira estrutura henge, localizada na península ibérica e foi descuberta en 2006 durante a construción da A-8, que tivo que variar o seu trazado para salvagardalo.',43.5395144,-7.1692357,'https://gl.wikipedia.org/wiki/Henge_de_Roda');
