INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181367,'17161','Roques Encantades','misterio','misterio_osm','Les roques encantades (o roques encadenades) és un conjunt de Roques que hi ha a la comarca de la Garrotxa, dins de la Fageda prop de la carretera que porta al Far. El nom del conjunt de roques ve de la llegenda que diu: "El Dimoni, que vivia per aquelles contrades quan estava de mala lluna passava l''estona fent…',42.0525985,2.5042612,'https://ca.wikipedia.org/wiki/Les_Roques_Encantades');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181368,'17043','Cova de les Encantades','misterio','misterio_osm','La Cova de les Encantades es troba a 2.027 m d''altitud a mà dreta pujant pel torrent de l''Estremera, a la Costa de les Tutes (Puigmal). Té un recorregut de 864 m i un desnivell de 37 m (-15 i +22) pel qual és considerada de les més llargues de la província de Girona.',42.361027,2.1141232,'https://ca.wikipedia.org/wiki/Cova_de_les_Encantades');
