INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(181374,'36008','Poza da Moura','misterio','misterio_osm','A poza da Moura son unhas pozas froito do río Freixa na parroquia de Domaio (Moaña). A poza e mailo sendeiro que percorre as distintas fervenzas contan con muíños e canalizacións antigas, así como camiños tradicionais.',42.298116,-8.68334,'https://gl.wikipedia.org/wiki/Poza_da_Moura');
